import{_ as o,c as a,o as i,ae as e}from"./chunks/framework.Bi6zybwU.js";const u=JSON.parse('{"title":"How to Customize Charts in Ninja Charts","description":"How to Customize Charts in Ninja Charts","frontmatter":{"title":"How to Customize Charts in Ninja Charts","description":"How to Customize Charts in Ninja Charts"},"headers":[],"relativePath":"guide/ninja-charts/how-to-customize-charts-in-ninja-charts.md","filePath":"guide/ninja-charts/how-to-customize-charts-in-ninja-charts.md"}'),r={name:"guide/ninja-charts/how-to-customize-charts-in-ninja-charts.md"};function n(s,t,l,h,c,d){return i(),a("div",null,[...t[0]||(t[0]=[e('<h1 id="how-to-customize-charts-in-ninja-charts" tabindex="-1">How to Customize Charts in Ninja Charts <a class="header-anchor" href="#how-to-customize-charts-in-ninja-charts" aria-label="Permalink to &quot;How to Customize Charts in Ninja Charts&quot;">​</a></h1><p>Ninja Charts is perfect for creating and embedding unlimited responsive online charts in WordPress websites. You can also customize charts however you need. This plugin gives you lots of flexibility and fun when it comes to customizing a data chart! In the <strong>Formatting &amp; Preview</strong> step, you’ll see some advanced options for customizing your charts.</p><h2 id="customizing-wordpress-charts-in-ninja-charts" tabindex="-1">Customizing WordPress Charts in Ninja Charts <a class="header-anchor" href="#customizing-wordpress-charts-in-ninja-charts" aria-label="Permalink to &quot;Customizing WordPress Charts in Ninja Charts&quot;">​</a></h2><p>We have this simple guide to show you how to customize Ninja Charts and have fun doing it! Here are the chart customizing options in the <strong>Formatting &amp; Preview</strong> step. You can customize Google Charts and Chart Js both following this tutorial.</p><h3 id="chart" tabindex="-1">CHART <a class="header-anchor" href="#chart" aria-label="Permalink to &quot;CHART&quot;">​</a></h3><p>In this tab, 8 customizing options will appear with features like chart coloring, size, fonts, etc. <img src="https://ninjatables.com/wp-content/uploads/2023/10/Chart--scaled.webp" alt=""></p><ul><li><strong>Responsive chart:</strong> Make a responsive online chart by toggling it on.</li><li><strong>Chart width:</strong> Customize chart width.</li><li><strong>Chart height:</strong> Customize chart height.</li><li><strong>Background color:</strong> Change the color of the chart background.</li><li><strong>Border width:</strong> Customize border width.</li><li><strong>Border color:</strong> Change border color.</li><li><strong>Border radius:</strong> Custom chart border radius.</li></ul><h3 id="series" tabindex="-1">SERIES <a class="header-anchor" href="#series" aria-label="Permalink to &quot;SERIES&quot;">​</a></h3><p>You can redefine the series labels and colors from here. <img src="https://ninjatables.com/wp-content/uploads/2023/10/Series-scaled.webp" alt=""></p><h3 id="axes" tabindex="-1">AXES <a class="header-anchor" href="#axes" aria-label="Permalink to &quot;AXES&quot;">​</a></h3><p>Show grid, control chart stack, or labels. <img src="https://ninjatables.com/wp-content/uploads/2023/10/Axies-scaled.webp" alt=""> Grid true and Grid false vary in different chart types. Here&#39;s a Horizontal bar chart with Grid true where you can customize what you need. Grid false appears for charts like Pie charts.</p><ul><li><strong>Show grid:</strong> Turn it off if you want grid lines in the chart background.</li><li><strong>Show stacked chart:</strong> Turn it off if you want the chart data to stack (This won&#39;t appear for charts like Pie Chart).</li><li><strong>Horizontal axis label</strong>: Custom labeling of the horizontal axis.</li><li><strong>Vertical axis label:</strong> Custom labeling of the vertical axis.</li><li><strong>Vertical axis min:</strong> Custom minimum value of the vertical axis.</li><li><strong>Vertical axis max:</strong> Custom maximum value of the vertical axis.</li></ul><h3 id="title" tabindex="-1">TITLE <a class="header-anchor" href="#title" aria-label="Permalink to &quot;TITLE&quot;">​</a></h3><p>Control chart title visibility, appearance, and position. <img src="https://ninjatables.com/wp-content/uploads/2023/10/Title-scaled.webp" alt=""></p><ul><li><strong>Show title:</strong> Toggle on if you want the chart title to show up.</li><li><strong>Title position:</strong> Change chart title position- Top, Bottom, Left, and Right.</li><li><strong>Title font style:</strong> Change chart title font- Normal, Italic, Bold.</li><li><strong>Title font color:</strong> Customize the title font color from the RGB palette.</li><li><strong>Font size:</strong> Change font size.</li></ul><h3 id="tooltip" tabindex="-1">TOOLTIP <a class="header-anchor" href="#tooltip" aria-label="Permalink to &quot;TOOLTIP&quot;">​</a></h3><p>Control chart tooltip appearance, visibility, and width. <img src="https://ninjatables.com/wp-content/uploads/2023/10/Tooltip-scaled.webp" alt=""></p><ul><li><strong>Show tooltip:</strong> Turn it on for the tooltip to appear.</li><li><strong>Background color:</strong> Change the tooltip background color.</li><li><strong>Border color:</strong> Change the tooltip border color.</li><li><strong>Title font color:</strong> Custom tooltip font color.</li><li><strong>Body font color:</strong> Custom tooltip font color.</li><li><strong>Border width:</strong> Pixel width of the tooltip border.</li><li><strong>Shared tooltip:</strong> Turn it on to share the tooltip area with the entire plot.</li></ul><h3 id="legend" tabindex="-1">LEGEND <a class="header-anchor" href="#legend" aria-label="Permalink to &quot;LEGEND&quot;">​</a></h3><p>Customize legend position and appearance. <img src="https://ninjatables.com/wp-content/uploads/2023/10/Legenda-scaled.webp" alt=""></p><ul><li><strong>Show legend:</strong> Enable or disable legend.</li><li><strong>Legend position:</strong> Position of legend- Top, Bottom, Left, Right.</li><li><strong>Font color:</strong> Change the legend font color.</li></ul><h3 id="layout" tabindex="-1">LAYOUT <a class="header-anchor" href="#layout" aria-label="Permalink to &quot;LAYOUT&quot;">​</a></h3><p>Customize chart padding when you embed it on your website.</p><ul><li>Padding left</li><li>Padding right</li><li>Padding top</li><li>Padding bottom <img src="https://ninjatables.com/wp-content/uploads/2023/10/Layout-scaled.webp" alt=""></li></ul><h3 id="chart-animations" tabindex="-1">CHART ANIMATIONS <a class="header-anchor" href="#chart-animations" aria-label="Permalink to &quot;CHART ANIMATIONS&quot;">​</a></h3><p>Customize chart render animation and select the animation ease type used to render the chart provided by Chart JS. <img src="https://ninjatables.com/wp-content/uploads/2023/10/animations-scaled.webp" alt=""> Create customizable charts and graphs easily using Ninja Charts.</p>',26)])])}const p=o(r,[["render",n]]);export{u as __pageData,p as default};
